def __init__(self, sec: float, nsec: float) -> None:
    if nsec < 0 or nsec >= 1e9:
        raise ValueError(f"Invalid value for nanoseconds in Timestamp: {nsec}")
    if sec < 0:
        nsec = -nsec
    self.sec: int = int(sec)
    self.nsec: int = int(nsec)

